ALTER TABLE public.cultural_inspirations ADD COLUMN quest_length text NOT NULL DEFAULT 'quick' CHECK (quest_length IN ('quick','classic','deep'));
CREATE OR REPLACE FUNCTION public.culture_quest_stats(p_card uuid) RETURNS jsonb LANGUAGE sql SECURITY INVOKER SET search_path=public AS $$ SELECT CASE WHEN EXISTS (SELECT 1 FROM public.cultural_inspirations c WHERE c.id=p_card AND (c.creator_id=auth.uid() OR c.partner_id=auth.uid()) AND trip_private.is_trip_member(c.trip_id,auth.uid()) AND trip_private.feature_on(c.trip_id,'inspiration')) THEN jsonb_build_object('plays',(SELECT count(*) FROM public.culture_quest_players p JOIN public.culture_quest_sessions s ON s.id=p.session_id WHERE s.card_id=p_card),'completed',(SELECT count(DISTINCT p.user_id) FROM public.culture_quest_players p JOIN public.culture_quest_sessions s ON s.id=p.session_id WHERE s.card_id=p_card AND p.completed_at IS NOT NULL),'average',(SELECT coalesce(round(avg(p.score)),0) FROM public.culture_quest_players p JOIN public.culture_quest_sessions s ON s.id=p.session_id WHERE s.card_id=p_card AND p.completed_at IS NOT NULL),'reactions',(SELECT count(*) FROM public.inspiration_votes v WHERE v.card_id=p_card AND v.choice='love')) ELSE NULL END $$;
REVOKE ALL ON FUNCTION public.culture_quest_stats(uuid) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.culture_quest_stats(uuid) TO authenticated;